	// timeline functions:
	this.frame_94 = function() {
		this.stop();
		
		// 1. Inisialisasi txtWarning
		if (this.txtWarning) {
		    this.txtWarning.text = "";
		    this.txtWarning.font = "20px 'Cambria'";
		    this.txtWarning.x = 540;
		    this.txtWarning.y = 278;
		    this.txtWarning.textAlign = "center";
		}
		
		// 2. Fungsi pembuat input HTML dengan nilai absolut
		function buatInputHTML(id, x, y, w, h) {
		    var input = document.createElement("input");
		
		    input.id = id;
		    input.type = "text";
		
		    input.style.cssText =
		        "position:absolute;" +
		        "left:" + x + "px;" +
		        "top:" + y + "px;" +
		        "width:" + w + "px;" +
		        "height:" + h + "px;" +
		        "font-family:Arial;" +
		        "font-size:16px;" +
		        "padding: 0 10px;" +
		        "box-sizing: border-box;" +
		        "z-index: 100;";
		
		    document.body.appendChild(input);
		}
		
		// 3. Koordinat disesuaikan dengan posisi visual panggung utama
		if (!document.getElementById("inputNama")) {
		    buatInputHTML("inputNama", 350, 195, 190, 35);
		    buatInputHTML("inputKelas", 350, 255, 190, 35);
		}
		
		// 4. Logika Tombol Login
		if (this.btnLogin) {
		    this.btnLogin.cursor = "pointer";
		    this.btnLogin.removeAllEventListeners("click");
		
		    this.btnLogin.addEventListener("click", function() {
		        var elNama = document.getElementById("inputNama");
		        var elKelas = document.getElementById("inputKelas");
		
		        var valNama = elNama ? elNama.value.trim() : "";
		        var valKelas = elKelas ? elKelas.value.trim() : "";
		
		        if (valNama === "" || valKelas === "") {
		            if (this.txtWarning) {
		                this.txtWarning.text = "Kolom tidak boleh kosong";
		            }
		        } else {
		            window.namaUser = valNama;
		            window.kelasUser = valKelas;
		
		            if (elNama) elNama.remove();
		            if (elKelas) elKelas.remove();
		
		            // PINDAH KE SCENE 1 (FRAME PERTAMA / INDEX 0)
		            this.stage.getChildAt(0).gotoAndPlay(4);
		        }
		    }.bind(this));
		}
	}

